-- public.rarity_blood(p_rare text, p_channel text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.rarity_blood(p_rare text, p_channel text)
 RETURNS double precision
 LANGUAGE plpgsql
 STABLE
AS $function$
begin
  return (
select coalesce((select case when ch.blood is false then 1
                               when coalesce(ch.up, true) then r.blood else 1 / r.blood end
    from rarity_def r left join channel_def ch on ch.id = p_channel
    where r.id = p_rare), 1)
  );
end $function$
